//! The land outlines. data/land.tsv is generated by src/bin/land_gen.rs,
//! committed, and embedded in the binary, so loading it cannot fail at runtime:
//! a malformed line means the committed file is broken and panics in dev.

use crate::geo::LonLat;

const DATA: &str = include_str!("../data/land.tsv");

/// The outer rings of the world's landmasses, each a run of points that is not
/// explicitly closed: the last point joins the first.
pub fn load() -> Vec<Vec<LonLat>> {
    DATA.lines()
        .enumerate()
        .filter(|(_, line)| !line.is_empty() && !line.starts_with('#'))
        .map(|(i, line)| ring(line, i + 1))
        .collect()
}

fn ring(line: &str, lineno: usize) -> Vec<LonLat> {
    line.split_whitespace()
        .map(|pair| {
            let (lon, lat) = pair
                .split_once(',')
                .unwrap_or_else(|| panic!("data/land.tsv line {lineno}: bad pair {pair:?}"));
            LonLat {
                lon: degrees(lon, lineno, pair),
                lat: degrees(lat, lineno, pair),
            }
        })
        .collect()
}

fn degrees(value: &str, lineno: usize, pair: &str) -> f64 {
    value
        .parse()
        .unwrap_or_else(|_| panic!("data/land.tsv line {lineno}: bad pair {pair:?}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_a_ring() {
        assert_eq!(
            ring("-58.55,-51.10 -57.75,-51.55 -58.05,-51.90", 2),
            vec![
                LonLat {
                    lon: -58.55,
                    lat: -51.10
                },
                LonLat {
                    lon: -57.75,
                    lat: -51.55
                },
                LonLat {
                    lon: -58.05,
                    lat: -51.90
                },
            ]
        );
    }

    #[test]
    #[should_panic(expected = "line 7: bad pair \"-58.55\"")]
    fn rejects_a_point_without_a_latitude() {
        ring("-58.55", 7);
    }

    #[test]
    #[should_panic(expected = "line 7: bad pair \"-58.55,south\"")]
    fn rejects_an_unparseable_degree() {
        ring("-58.55,south", 7);
    }

    #[test]
    fn loads_the_committed_outlines() {
        let rings = load();
        assert!(rings.len() >= 100, "{} rings", rings.len());
        for ring in &rings {
            assert!(ring.len() >= 3, "a ring of {} points", ring.len());
            for point in ring {
                assert!(
                    (-180.0..=180.0).contains(&point.lon) && (-90.0..=90.0).contains(&point.lat),
                    "{point:?} is off the globe"
                );
            }
        }
    }
}
